"""A JobPilot workspace: the folder holding jobpilot.toml, your profile and all data. Nothing leaves it except
search filters (to Apify) and job descriptions plus your profile (to Claude)."""
import os
import shutil
from pathlib import Path

from . import __version__, config, util

PACKAGE = Path(__file__).resolve().parent
PLUGIN_ROOT = PACKAGE.parent

GITIGNORE = """# JobPilot workspace: personal data. Keep this folder private (never push it to a public repository).
.env
data/
.jobpilot/
tailored/**/*.pdf
!.gitignore
"""

WRAPPER = """#!/bin/sh
# JobPilot workspace launcher (generated by `jobpilot init`; safe to delete, `jobpilot init` recreates it).
# Runs the CLI copy in .jobpilot/runtime so terminals and scheduled runs work without Claude Code.
HERE="$(cd "$(dirname "$0")" && pwd)"
JOBPILOT_WORKSPACE="$HERE" exec "$HERE/.jobpilot/runtime/bin/jobpilot" "$@"
"""

CONFIG_TEMPLATE = """# JobPilot configuration. /jobpilot:setup fills this in from your resume; edit freely afterwards.
# Reference: https://github.com/ZhengShixin/JobPilot/blob/main/docs/configuration.md

[candidate]
name = "{name}"
resume = ""                       # your master resume, e.g. "profile/resume.docx"
work_authorization = ""           # us_citizen | permanent_resident | work_visa | needs_sponsorship | other
seniority = []                    # target levels: entry | mid | senior | lead
locations = ["United States"]     # Apify locationSearch format: "United States", "New York, New York, United States"
work_arrangements = []            # [] = any, or some of "On-site", "Hybrid", "Remote OK", "Remote Solely"
min_salary_usd = 0                # drop postings whose advertised annual maximum is below this (0 = off)
target_salary_usd = 0             # between the two: admitted, labeled "practice", queued last (0 = off)
languages = ["English"]
schools = []                      # your schools, for the alumni referral finder

[app]
language = "{language}"            # en | zh (dashboard and reports)
timezone = "{timezone}"

# [[tracks]] blocks and [search.groups.*] tables are designed by /jobpilot:setup.

[search]
daily_budget_usd = 1.00
monthly_budget_usd = 25.00
run_time = "07:30"
"""


# The same launcher as the plugin's bin/jobpilot (a pip/pipx install has no bin/ folder next to the package).
LAUNCHER = """#!/bin/sh
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
for py in "$JOBPILOT_PYTHON" python3.14 python3.13 python3.12 python3.11 python3 /opt/homebrew/bin/python3 /usr/local/bin/python3; do
  [ -n "$py" ] || continue
  command -v "$py" >/dev/null 2>&1 || continue
  if "$py" -c 'import sys; sys.exit(0 if sys.version_info >= (3, 11) else 1)' 2>/dev/null; then
    exec "$py" -I -c 'import sys; sys.path.insert(0, sys.argv[1]); from jobpilot.cli import main; sys.exit(main(sys.argv[2:]))' "$ROOT" "$@"
  fi
done
echo "JobPilot needs Python 3.11 or newer (set JOBPILOT_PYTHON to an interpreter)." >&2
exit 1
"""


class NotFound(util.JobPilotError):
    pass


class Workspace:
    def __init__(self, root):
        self.root = Path(root).expanduser().resolve()
        self._cfg = None
        self._db = None

    # ------------------------------------------------------------ paths
    @property
    def config_path(self):
        return self.root / "jobpilot.toml"

    profile = property(lambda s: s.root / "profile")
    profile_md = property(lambda s: s.profile / "profile.md")
    claims_md = property(lambda s: s.profile / "claims.md")
    rubric_md = property(lambda s: s.profile / "rubric.md")
    examples_path = property(lambda s: s.profile / "plan-examples.json")
    outreach_md = property(lambda s: s.profile / "outreach.md")
    data = property(lambda s: s.root / "data")
    jds = property(lambda s: s.data / "jds")
    runs = property(lambda s: s.data / "runs")
    logs = property(lambda s: s.data / "logs")
    cache = property(lambda s: s.data / "cache")
    locks = property(lambda s: s.data / "locks")
    network = property(lambda s: s.data / "network")
    inbox = property(lambda s: s.data / "inbox")
    db_path = property(lambda s: s.data / "jobpilot.db")
    apps_path = property(lambda s: s.data / "apps.jsonl")
    budget_path = property(lambda s: s.data / "budget.jsonl")
    events_path = property(lambda s: s.data / "events.jsonl")
    claude_runs_path = property(lambda s: s.data / "claude-runs.jsonl")
    pool_events_path = property(lambda s: s.data / "pool-events.jsonl")
    tailored = property(lambda s: s.root / "tailored")
    reports = property(lambda s: s.root / "reports" / "daily")
    runtime = property(lambda s: s.root / ".jobpilot" / "runtime")

    def ensure(self):
        for p in (self.profile, self.data, self.jds, self.runs, self.logs, self.cache, self.locks, self.tailored,
                  self.reports, self.network, self.inbox):
            p.mkdir(parents=True, exist_ok=True)
        os.chmod(self.data, 0o700)
        return self

    # ------------------------------------------------------------ objects
    @property
    def cfg(self):
        if self._cfg is None:
            self._cfg = config.load(self.config_path)
        return self._cfg

    def reload(self):
        self._cfg = None
        return self.cfg

    @property
    def db(self):
        if self._db is None:
            from .db import DB
            self.ensure()
            self._db = DB(self.db_path)
        return self._db

    @property
    def tz(self):
        return util.zone((self.cfg.get("app") or {}).get("timezone") or None)

    def now(self):
        return util.now(self.tz)

    def today(self):
        return self.now().date().isoformat()

    def event(self, kind, text, **data):
        """One line in the activity feed (data/events.jsonl) that the dashboard and the daily report show."""
        rec = {"kind": kind, "text": text}
        if data:
            rec["data"] = data
        return util.jsonl_append(self.events_path, rec)

    def lock(self, name, wait=True, timeout=None):
        return util.file_lock(self.locks / ("%s.lock" % name), wait=wait, timeout=timeout)

    def rel(self, path):
        try:
            return str(Path(path).resolve().relative_to(self.root))
        except ValueError:
            return str(path)

    def __repr__(self):
        return "Workspace(%s)" % self.root


def find(start=None, explicit=None):
    """The workspace named by `explicit`, $JOBPILOT_WORKSPACE, or the nearest folder with jobpilot.toml at or above
    `start` (default: the current directory)."""
    target = explicit or os.environ.get("JOBPILOT_WORKSPACE")
    if target:
        ws = Workspace(target)
        if not ws.config_path.exists():
            raise NotFound("%s has no jobpilot.toml; run `jobpilot init %s` first" % (ws.root, target))
        return ws
    here = Path(start or os.getcwd()).resolve()
    for folder in (here, *here.parents):
        if (folder / "jobpilot.toml").exists():
            return Workspace(folder)
    raise NotFound("no JobPilot workspace here (no jobpilot.toml in %s or above). Run /jobpilot:setup in the folder "
                   "you want to use, or `jobpilot init <folder>`." % here)


def init(root, name="", language="en", timezone=None):
    """Create a workspace (idempotent: existing files are never overwritten). Returns (workspace, created files)."""
    ws = Workspace(root)
    ws.root.mkdir(parents=True, exist_ok=True)
    ws.ensure()
    created = []
    lang = "zh" if str(language).lower().startswith("zh") else "en"
    files = {
        ws.config_path: CONFIG_TEMPLATE.format(name=name.replace('"', ""), language=lang,
                                               timezone=timezone or util.system_timezone()),
        ws.root / ".gitignore": GITIGNORE,
    }
    for path, text in files.items():
        if not path.exists():
            util.atomic_write_text(path, text)
            created.append(ws.rel(path))
    sync_runtime(ws, force=False)
    wrapper = ws.root / "jobpilot"
    if not wrapper.exists():
        util.atomic_write_text(wrapper, WRAPPER, mode=0o755)
        created.append("jobpilot")
    return ws, created


_DIGEST = {}


def package_digest():
    """sha256 over this package's files (the runtime copy is refreshed whenever the code changes, not only on a new
    version number)."""
    if "v" not in _DIGEST:
        import hashlib
        h = hashlib.sha256(__version__.encode())
        for base in (PACKAGE,):
            for p in sorted(base.rglob("*")):
                if p.is_file() and "__pycache__" not in p.parts and p.suffix != ".pyc":
                    h.update(str(p.relative_to(PLUGIN_ROOT)).encode())
                    h.update(p.read_bytes())
        _DIGEST["v"] = h.hexdigest()[:16]
    return _DIGEST["v"]


def sync_runtime(ws, force=False):
    """Keep .jobpilot/runtime (used by ./jobpilot and scheduled runs) identical to this package. Returns True when
    it copied. Skipped when this code already runs from the runtime copy."""
    target = ws.runtime
    if PLUGIN_ROOT.resolve() == target.resolve():
        return False
    stamp_file = target / "VERSION"
    current = stamp_file.read_text().strip() if stamp_file.exists() else ""
    wanted = "%s %s" % (__version__, package_digest())
    if current == wanted and not force:
        return False
    tmp = target.with_name("runtime.tmp")
    if tmp.exists():
        shutil.rmtree(tmp)
    shutil.copytree(PACKAGE, tmp / "jobpilot", ignore=shutil.ignore_patterns("__pycache__", "*.pyc"))
    (tmp / "bin").mkdir()
    util.atomic_write_text(tmp / "bin" / "jobpilot", LAUNCHER, mode=0o755)
    (tmp / "VERSION").write_text(wanted + "\n")
    if target.exists():
        shutil.rmtree(target)
    tmp.rename(target)
    return True
